    {
      "i": 1,
      "speaker": "caller",
      "text": "जी।"
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "ठीक है मैं Tanya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "हमारे पास कई अच्छे sellers available हैं जिससे मैं अभी आपको connect करवाऊंगी।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "बस एक छोटी सी detail confirm कर दूं।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "आपको यह किस काम के लिए चाहिए?"
    },
    {
      "i": 6,
      "speaker": "bot",
      "text": "For reselling, for business use या for home use?"
    },
    {
      "i": 7,
      "speaker": "caller",
      "text": "एक second."
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "बिल्कुल आप आराम से बताइए।"
    },
    {
      "i": 9,
      "speaker": "caller",
      "text": "Madam."
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "जी बोलिए।"
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "क्या आप factory के लिए available है आपके पास?"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "माफ़ कीजिए मैं केवल IndiaMART से जुड़ी product और services में ही आपकी मदद कर सकती हूं।"
    }
  ]
